+            for (char[] row : chars) {
+                Arrays.fill(row, ' ');
+            }
+            for (int row = 0; row < expanded.size(); row++) {
+                String line = expanded.get(row);
+                for (int col = 0; col < line.length(); col++) {
+                    chars[row + PAD][col + PAD] = line.charAt(col);
+                }
+            }
+            return new Grid(chars);
+        }
+
+        char charAt(int row, int col) {
+            if (row < 0 || row >= height || col < 0 || col >= width) {
+                return ' ';
+            }
+            return chars[row][col];
+        }
+
+        private static String expandTabs(String line, int tabs) {
+            if (tabs <= 0 || line.indexOf('\t') < 0) {
+                return line;
+            }
+            StringBuilder builder = new StringBuilder();
+            int column = 0;
+            for (int i = 0; i < line.length(); i++) {
+                char ch = line.charAt(i);
+                if (ch == '\t') {
+                    int spaces = tabs - (column % tabs);
+                    for (int j = 0; j < spaces; j++) {
+                        builder.append(' ');
+                        column++;
+                    }
+                } else {
+                    builder.append(ch);
+                    column++;
+                }
+            }
+            return builder.toString();
+        }
+    }
