+    private static final class Diagram {
+        final Grid grid;
+        final List<ShapeRegion> shapes;
+        final List<LinePath> lines;
+        final List<TextItem> freeText;
+        final List<Marker> markers;
+
+        Diagram(Grid grid, List<ShapeRegion> shapes, List<LinePath> lines,
+                List<TextItem> freeText, List<Marker> markers) {
+            this.grid = grid;
+            this.shapes = shapes;
+            this.lines = lines;
+            this.freeText = freeText;
+            this.markers = markers;
+        }
+
+        static Diagram analyze(Grid grid, Options options) {
+            Graph graph = Graph.build(grid);
+            List<Face> faces = graph.findFaces();
+            List<ShapeRegion> shapes = new ArrayList<>();
+            for (Face face : faces) {
+                shapes.add(ShapeRegion.fromFace(face, grid, options));
+            }
+            shapes.sort(Comparator.comparingDouble((ShapeRegion s) -> -Math.abs(s.face.area)));
+
+            Set<Edge> shapeEdges = new HashSet<>();
+            for (ShapeRegion shape : shapes) {
+                shapeEdges.addAll(shape.face.edges);
+            }
+
+            List<LinePath> lines = graph.findOpenLines(shapeEdges, options);
+            List<Marker> markers = graph.findMarkers();
+            List<TextItem> freeText = collectFreeText(grid, shapes, graph);
+            return new Diagram(grid, shapes, lines, freeText, markers);
+        }
+
+        private static List<TextItem> collectFreeText(Grid grid, List<ShapeRegion> shapes, Graph graph) {
+            List<TextItem> items = new ArrayList<>();
+            boolean[][] insideShape = new boolean[grid.height][grid.width];
+            for (ShapeRegion shape : shapes) {
+                for (int row = shape.minRow; row <= shape.maxRow; row++) {
+                    for (int col = shape.minCol; col <= shape.maxCol; col++) {
+                        if (shape.contains(col, row)) {
+                            insideShape[row][col] = true;
+                        }
+                    }
+                }
+            }
+
+            for (int row = 0; row < grid.height; row++) {
+                int col = 0;
+                while (col < grid.width) {
+                    if (insideShape[row][col] || graph.isLineGlyph(row, col)) {
+                        col++;
+                        continue;
+                    }
+                    char ch = grid.charAt(row, col);
+                    if (ch == ' ') {
+                        col++;
+                        continue;
+                    }
+                    int start = col;
+                    StringBuilder text = new StringBuilder();
+                    while (col < grid.width && !insideShape[row][col] && !graph.isLineGlyph(row, col)) {
+                        char curr = grid.charAt(row, col);
+                        if (curr == ' ') {
+                            break;
+                        }
+                        text.append(curr);
+                        col++;
+                    }
+                    if (text.length() > 0) {
+                        items.add(new TextItem(text.toString(), start, row, null, false));
+                    } else {
+                        col++;
+                    }
+                }
+            }
+            return items;
+        }
+    }
