+    private static final class ShapeRegion {
+        final Face face;
+        final ShapeKind kind;
+        final Color fill;
+        final Color textColor;
+        final List<TextItem> text;
+        final int minCol;
+        final int maxCol;
+        final int minRow;
+        final int maxRow;
+        final boolean roundCorners;
+
+        ShapeRegion(Face face, ShapeKind kind, Color fill, Color textColor,
+                    List<TextItem> text, boolean roundCorners) {
+            this.face = face;
+            this.kind = kind;
+            this.fill = fill;
+            this.textColor = textColor;
+            this.text = text;
+            this.roundCorners = roundCorners;
+            int minCol = Integer.MAX_VALUE;
+            int maxCol = Integer.MIN_VALUE;
+            int minRow = Integer.MAX_VALUE;
+            int maxRow = Integer.MIN_VALUE;
+            for (Node node : face.polygon) {
+                minCol = Math.min(minCol, node.col);
+                maxCol = Math.max(maxCol, node.col);
+                minRow = Math.min(minRow, node.row);
+                maxRow = Math.max(maxRow, node.row);
+            }
+            this.minCol = minCol;
+            this.maxCol = maxCol;
+            this.minRow = minRow;
+            this.maxRow = maxRow;
+        }
+
+        static ShapeRegion fromFace(Face face, Grid grid, Options options) {
+            String tag = null;
+            Color fill = Color.WHITE;
+            List<TextItem> textItems = new ArrayList<>();
+            for (int row = minRow(face); row <= maxRow(face); row++) {
+                StringBuilder inside = new StringBuilder();
+                int runStart = -1;
+                for (int col = minCol(face); col <= maxCol(face); col++) {
+                    if (contains(face.polygon, col, row)) {
+                        if (runStart < 0) {
+                            runStart = col;
+                        }
+                        inside.append(grid.charAt(row, col));
+                    } else if (runStart >= 0) {
+                        RowText parsed = parseRowText(inside.toString(), runStart, row);
+                        if (parsed.tag != null) {
+                            tag = parsed.tag;
+                        }
+                        if (parsed.fill != null) {
+                            fill = parsed.fill;
+                        }
+                        if (parsed.text != null) {
+                            textItems.add(parsed.text);
+                        }
+                        inside.setLength(0);
+                        runStart = -1;
+                    }
+                }
+                if (runStart >= 0) {
+                    RowText parsed = parseRowText(inside.toString(), runStart, row);
+                    if (parsed.tag != null) {
+                        tag = parsed.tag;
+                    }
+                    if (parsed.fill != null) {
+                        fill = parsed.fill;
+                    }
+                    if (parsed.text != null) {
+                        textItems.add(parsed.text);
+                    }
+                }
+            }
+
+            ShapeKind kind = ShapeKind.PLAIN;
+            if (isRectangle(face.polygon)) {
+                if ("d".equals(tag)) {
+                    kind = ShapeKind.DOCUMENT;
+                } else if ("s".equals(tag)) {
+                    kind = ShapeKind.STORAGE;
+                } else if ("o".equals(tag)) {
+                    kind = ShapeKind.ELLIPSE;
+                } else if ("c".equals(tag)) {
+                    kind = ShapeKind.CHOICE;
+                } else if ("io".equals(tag)) {
+                    kind = options.fixedSlope ? ShapeKind.IO_FIXED : ShapeKind.IO;
+                } else if ("tr".equals(tag)) {
+                    kind = options.fixedSlope ? ShapeKind.TRAPEZOID_FIXED : ShapeKind.TRAPEZOID;
+                } else if ("mo".equals(tag)) {
+                    kind = ShapeKind.MANUAL_OPERATION;
+                }
+            }
+            boolean rounded = options.roundCorners || hasRoundedCorners(face.polygon, grid);
+            Color textColor = chooseTextColor(fill);
+            return new ShapeRegion(face, kind, fill, textColor, textItems, rounded);
+        }
+
+        boolean contains(int col, int row) {
+            return contains(face.polygon, col, row);
+        }
+    }
