+                        .append("' ><![CDATA[").append(escapeCdata(text.text)).append("]]></text>\n");
+                }
+            }
+            for (LinePath line : diagram.lines) {
+                ShapeGeometry geometry = ShapeGeometry.forLine(line, options);
+                out.append("    <path stroke='#000000' stroke-width='").append(oneDecimal(options.scale)).append("'");
+                if (line.dashed) {
