+                setHints(shadowGraphics, options);
+                shadowGraphics.setComposite(AlphaComposite.SrcOver);
+                shadowGraphics.setColor(new Color(128, 128, 128, 180));
+                for (ShapeRegion shape : diagram.shapes) {
+                    ShapeGeometry geometry = ShapeGeometry.forShape(shape, options);
+                    shadowGraphics.fill(geometry.shadowPath);
+                }
+                shadowGraphics.dispose();
+                shadow = blur(shadow, Math.max(1, (int) Math.round(3 * options.scale)));
+                graphics.drawImage(shadow, 0, 0, null);
+            }
+
+            for (ShapeRegion shape : diagram.shapes) {
+                ShapeGeometry geometry = ShapeGeometry.forShape(shape, options);
+                if (!options.noSeparation) {
+                    graphics.setColor(Color.WHITE);
+                    graphics.setStroke(new BasicStroke((float) Math.max(1.0, 3.0 * options.scale),
+                        BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
+                    graphics.draw(geometry.outlinePath);
+                }
+                graphics.setColor(shape.fill);
+                graphics.fill(geometry.fillPath);
+                graphics.setColor(Color.BLACK);
+                graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
+                    BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
+                graphics.draw(geometry.outlinePath);
+                for (Path2D extra : geometry.extraPaths) {
+                    graphics.draw(extra);
+                }
+                for (TextItem text : shape.text) {
+                    if (text.text.isEmpty()) {
+                        continue;
+                    }
+                    int fontSize = fitFontSize(text.text, text.col, text.row, shape, options.scale);
+                    Font font = new Font("Courier", Font.BOLD, fontSize);
+                    graphics.setFont(font);
+                    graphics.setColor(shape.textColor);
+                    graphics.drawString(text.text, textStartX(text.col, options.scale), textBaselineY(text.row, options.scale));
+                }
+            }
+
+            graphics.setColor(Color.BLACK);
+            for (LinePath line : diagram.lines) {
+                ShapeGeometry geometry = ShapeGeometry.forLine(line, options);
+                if (line.dashed) {
+                    float dash = (float) Math.max(1.0, 5.0 * options.scale);
+                    graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
+                        BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 10f, new float[] {dash, dash}, 0f));
+                } else {
+                    graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
+                        BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
+                }
+                graphics.draw(geometry.outlinePath);
+                for (Path2D extra : geometry.extraPaths) {
+                    graphics.fill(extra);
+                }
+            }
+
+            graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
+                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
+            graphics.setFont(new Font("Courier", Font.BOLD, scaledValue(15, options.scale)));
+            for (TextItem item : diagram.freeText) {
+                graphics.setColor(Color.BLACK);
+                graphics.drawString(item.text, textStartX(item.col, options.scale), textBaselineY(item.row, options.scale));
