+    private static final class ShapeGeometry {
+        final Path2D fillPath;
+        final Path2D outlinePath;
+        final Path2D shadowPath;
+        final String fillSvg;
+        final String outlineSvg;
+        final String shadowPathSvg;
+        final List<Path2D> extraPaths;
+        final List<String> extraSvg;
+
+        ShapeGeometry(Path2D fillPath, Path2D outlinePath, Path2D shadowPath,
+                      String fillSvg, String outlineSvg, String shadowPathSvg,
+                      List<Path2D> extraPaths, List<String> extraSvg) {
+            this.fillPath = fillPath;
+            this.outlinePath = outlinePath;
+            this.shadowPath = shadowPath;
+            this.fillSvg = fillSvg;
+            this.outlineSvg = outlineSvg;
+            this.shadowPathSvg = shadowPathSvg;
+            this.extraPaths = extraPaths;
+            this.extraSvg = extraSvg;
+        }
+
+        static ShapeGeometry forShape(ShapeRegion shape, Options options) {
+            Rect rect = boundingRect(shape.face.polygon, options.scale);
+            switch (shape.kind) {
+                case DOCUMENT:
+                    return document(rect, options);
+                case STORAGE:
+                    return storage(rect, options);
+                case ELLIPSE:
+                    return ellipse(rect, options);
+                case CHOICE:
+                    return choice(rect, options);
+                case IO:
+                    return io(rect, options, 5.0 * options.scale);
+                case IO_FIXED:
+                    return io(rect, options, 5.25 * options.scale);
+                case TRAPEZOID:
+                    return trapezoid(rect, options, 5.0 * options.scale, true);
+                case TRAPEZOID_FIXED:
+                    return trapezoid(rect, options, 5.25 * options.scale, true);
+                case MANUAL_OPERATION:
+                    return trapezoid(rect, options, 5.0 * options.scale, false);
+                default:
+                    return polygon(shape.face.polygon, shape.roundCorners, options);
+            }
+        }
+
+        static ShapeGeometry forLine(LinePath line, Options options) {
+            PathResult outline = buildLinePath(line.nodes, line.roundCorners, options);
+            List<Path2D> extras = new ArrayList<>();
+            List<String> extraSvg = new ArrayList<>();
+            addArrow(line.nodes, options, extras, extraSvg);
+            return new ShapeGeometry(outline.path, outline.path, outline.path,
+                outline.svg, outline.svg, outline.svg, extras, extraSvg);
+        }
+
+        private static ShapeGeometry polygon(List<Node> polygon, boolean roundCorners, Options options) {
+            PathResult result = buildPolygonPath(polygon, roundCorners, options);
+            Path2D shadowPath = translate(result.path, 5.0 * options.scale, 5.0 * options.scale);
+            String shadowSvg = translateSvg(result.svg, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(result.path, result.path, shadowPath, result.svg, result.svg, shadowSvg,
+                new ArrayList<>(), new ArrayList<>());
+        }
