+        private static ShapeGeometry document(Rect rect, Options options) {
+            Path2D path = new Path2D.Double();
+            path.moveTo(rect.left, rect.top);
+            path.lineTo(rect.right, rect.top);
+            path.lineTo(rect.right, rect.bottom);
+            double cp1x = rect.right - (rect.width() / 3.0);
+            double cp2x = rect.left + (rect.width() / 3.0);
+            double midx = rect.left + rect.width() / 2.0;
+            path.quadTo(cp1x, rect.bottom - 8.0 * options.scale, midx, rect.bottom);
+            path.quadTo(cp2x, rect.bottom + 8.0 * options.scale, rect.left, rect.bottom);
+            path.closePath();
+            String svg = "M" + oneDecimal(rect.left) + " " + oneDecimal(rect.top) +
+                " L" + oneDecimal(rect.right) + " " + oneDecimal(rect.top) +
+                " L" + oneDecimal(rect.right) + " " + oneDecimal(rect.bottom) +
+                " Q" + oneDecimal(cp1x) + " " + oneDecimal(rect.bottom - 8.0 * options.scale) +
+                " " + oneDecimal(midx) + " " + oneDecimal(rect.bottom) +
+                " Q" + oneDecimal(cp2x) + " " + oneDecimal(rect.bottom + 8.0 * options.scale) +
+                " " + oneDecimal(rect.left) + " " + oneDecimal(rect.bottom) + " z";
+            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
+                new ArrayList<>(), new ArrayList<>());
+        }
+
+        private static ShapeGeometry storage(Rect rect, Options options) {
+            double ctrl = rect.width() / 6.0;
+            double ry = 7.0 * options.scale;
+            Path2D fill = new Path2D.Double();
+            fill.moveTo(rect.left, rect.top);
+            fill.curveTo(rect.left + ctrl, rect.top + ry, rect.right - ctrl, rect.top + ry, rect.right, rect.top);
+            fill.lineTo(rect.right, rect.bottom);
+            fill.curveTo(rect.right - ctrl, rect.bottom + 10.0 * options.scale, rect.left + ctrl, rect.bottom + 10.0 * options.scale, rect.left, rect.bottom);
+            fill.closePath();
+
+            Path2D outline = new Path2D.Double();
+            outline.moveTo(rect.left, rect.top);
+            outline.curveTo(rect.left + ctrl, rect.top + ry, rect.right - ctrl, rect.top + ry, rect.right, rect.top);
+            outline.curveTo(rect.right - ctrl, rect.top - ry, rect.left + ctrl, rect.top - ry, rect.left, rect.top);
+            outline.moveTo(rect.left, rect.top);
+            outline.lineTo(rect.left, rect.bottom);
+            outline.curveTo(rect.left + ctrl, rect.bottom + 10.0 * options.scale, rect.right - ctrl, rect.bottom + 10.0 * options.scale, rect.right, rect.bottom);
+            outline.lineTo(rect.right, rect.top);
+
+            String fillSvg = pathToSvg(fill);
+            String outlineSvg = pathToSvg(outline);
+            Path2D shadow = translate(outline, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(fill, outline, shadow, fillSvg, outlineSvg,
+                translateSvg(outlineSvg, 5.0 * options.scale, 5.0 * options.scale),
+                new ArrayList<>(), new ArrayList<>());
+        }
+
+        private static ShapeGeometry ellipse(Rect rect, Options options) {
+            Path2D path = new Path2D.Double();
+            path.moveTo(rect.centerX(), rect.top);
+            path.curveTo(rect.right, rect.top, rect.right, rect.centerY(), rect.right, rect.centerY());
+            path.curveTo(rect.right, rect.bottom, rect.centerX(), rect.bottom, rect.centerX(), rect.bottom);
+            path.curveTo(rect.left, rect.bottom, rect.left, rect.centerY(), rect.left, rect.centerY());
+            path.curveTo(rect.left, rect.top, rect.centerX(), rect.top, rect.centerX(), rect.top);
+            path.closePath();
+            String svg = pathToSvg(path);
+            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
+                new ArrayList<>(), new ArrayList<>());
+        }
+
+        private static ShapeGeometry choice(Rect rect, Options options) {
+            Path2D path = new Path2D.Double();
+            path.moveTo(rect.left, rect.centerY());
+            path.lineTo(rect.centerX(), rect.top);
+            path.lineTo(rect.right, rect.centerY());
+            path.lineTo(rect.centerX(), rect.bottom);
+            path.closePath();
+            String svg = pathToSvg(path);
+            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
+                new ArrayList<>(), new ArrayList<>());
+        }
+
+        private static ShapeGeometry io(Rect rect, Options options, double dx) {
+            Path2D path = new Path2D.Double();
+            path.moveTo(rect.left + dx, rect.top);
+            path.lineTo(rect.right + dx, rect.top);
+            path.lineTo(rect.right - dx, rect.bottom);
+            path.lineTo(rect.left - dx, rect.bottom);
+            path.closePath();
+            String svg = pathToSvg(path);
+            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
+                new ArrayList<>(), new ArrayList<>());
+        }
+
+        private static ShapeGeometry trapezoid(Rect rect, Options options, double dx, boolean topNarrow) {
+            Path2D path = new Path2D.Double();
+            if (topNarrow) {
+                path.moveTo(rect.left + dx, rect.top);
+                path.lineTo(rect.right - dx, rect.top);
+                path.lineTo(rect.right + dx, rect.bottom);
+                path.lineTo(rect.left - dx, rect.bottom);
+            } else {
+                path.moveTo(rect.left - dx, rect.top);
+                path.lineTo(rect.right + dx, rect.top);
+                path.lineTo(rect.right - dx, rect.bottom);
+                path.lineTo(rect.left + dx, rect.bottom);
+            }
+            path.closePath();
+            String svg = pathToSvg(path);
+            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
+            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
+                new ArrayList<>(), new ArrayList<>());
+        }
+
+        private static void addArrow(List<Node> nodes, Options options, List<Path2D> extras, List<String> extraSvg) {
+            if (nodes.isEmpty()) {
+                return;
+            }
+            Node first = nodes.get(0);
+            Node last = nodes.get(nodes.size() - 1);
+            if (isArrow(first.ch)) {
+                Path2D path = arrowPath(first.ch, coordX(first.col, options.scale), coordY(first.row, options.scale), options.scale);
+                extras.add(path);
+                extraSvg.add("<path stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='" + pathToSvg(path) + "' />");
+            }
+            if (isArrow(last.ch)) {
+                Path2D path = arrowPath(last.ch, coordX(last.col, options.scale), coordY(last.row, options.scale), options.scale);
+                extras.add(path);
+                extraSvg.add("<path stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='" + pathToSvg(path) + "' />");
+            }
+        }
+    }
