+    private static final class PathResult {
+        final Path2D path;
+        final String svg;
+
+        PathResult(Path2D path, String svg) {
+            this.path = path;
+            this.svg = svg;
+        }
+    }
+
+    private static PathResult buildPolygonPath(List<Node> polygon, boolean roundCorners, Options options) {
+        List<Point2D.Double> points = new ArrayList<>();
+        List<Boolean> rounded = new ArrayList<>();
+        for (Node node : polygon) {
+            points.add(new Point2D.Double(coordX(node.col, options.scale), coordY(node.row, options.scale)));
+            rounded.add(roundCorners || node.ch == '/' || node.ch == '\\');
+        }
+        return buildPath(points, rounded, true);
+    }
+
+    private static PathResult buildLinePath(List<Node> nodes, boolean roundCorners, Options options) {
+        List<Point2D.Double> points = new ArrayList<>();
+        List<Boolean> rounded = new ArrayList<>();
+        for (Node node : nodes) {
+            points.add(new Point2D.Double(coordX(node.col, options.scale), coordY(node.row, options.scale)));
+            rounded.add(roundCorners || node.ch == '/' || node.ch == '\\');
+        }
+        return buildPath(points, rounded, false);
+    }
+
+    private static PathResult buildPath(List<Point2D.Double> points, List<Boolean> rounded, boolean closed) {
+        Path2D path = new Path2D.Double();
+        StringBuilder svg = new StringBuilder();
+        int n = points.size();
+        if (n == 0) {
+            return new PathResult(path, "");
+        }
+        if (closed && !points.isEmpty() && points.get(0).equals(points.get(n - 1))) {
+            points = new ArrayList<>(points.subList(0, n - 1));
+            rounded = new ArrayList<>(rounded.subList(0, n - 1));
+            n = points.size();
+        }
+        if (n == 0) {
+            return new PathResult(path, "");
+        }
+        Point2D.Double start = points.get(0);
+        path.moveTo(start.x, start.y);
+        svg.append("M").append(oneDecimal(start.x)).append(" ").append(oneDecimal(start.y));
+        for (int i = 1; i < n; i++) {
+            Point2D.Double curr = points.get(i);
+            if (rounded.get(i) && i > 0 && i < n - 1) {
+                Point2D.Double prev = points.get(i - 1);
+                Point2D.Double next = points.get(i + 1);
+                Point2D.Double before = offsetTowards(curr, prev);
+                Point2D.Double after = offsetTowards(curr, next);
+                path.lineTo(before.x, before.y);
+                path.quadTo(curr.x, curr.y, after.x, after.y);
+                svg.append(" L").append(oneDecimal(before.x)).append(" ").append(oneDecimal(before.y))
+                    .append(" Q").append(oneDecimal(curr.x)).append(" ").append(oneDecimal(curr.y))
+                    .append(" ").append(oneDecimal(after.x)).append(" ").append(oneDecimal(after.y));
+            } else {
+                path.lineTo(curr.x, curr.y);
+                svg.append(" L").append(oneDecimal(curr.x)).append(" ").append(oneDecimal(curr.y));
+            }
+        }
+        if (closed) {
+            path.closePath();
+            svg.append(" z");
+        }
+        return new PathResult(path, svg.toString());
+    }
+
+    private static Point2D.Double offsetTowards(Point2D.Double from, Point2D.Double to) {
+        double dx = to.x - from.x;
+        double dy = to.y - from.y;
+        if (Math.abs(dx) > Math.abs(dy)) {
+            return new Point2D.Double(from.x + Math.signum(dx) * 5.0, from.y);
+        }
+        return new Point2D.Double(from.x, from.y + Math.signum(dy) * 7.0);
+    }
+
+    private static Path2D translate(Path2D path, double dx, double dy) {
+        Path2D copy = (Path2D) path.clone();
+        copy.transform(java.awt.geom.AffineTransform.getTranslateInstance(dx, dy));
+        return copy;
+    }
+
+    private static String translateSvg(String svg, double dx, double dy) {
+        StringBuilder out = new StringBuilder();
+        Matcher matcher = Pattern.compile("([MLQCA])|(-?\\d+(?:\\.\\d+)?)").matcher(svg);
+        List<String> tokens = new ArrayList<>();
+        while (matcher.find()) {
+            tokens.add(matcher.group());
+        }
+        boolean xCoord = false;
+        char mode = ' ';
+        for (String token : tokens) {
+            if (token.length() == 1 && Character.isLetter(token.charAt(0))) {
+                mode = token.charAt(0);
+                out.append(token);
+                if (mode == 'z' || mode == 'Z') {
+                    xCoord = false;
+                } else {
+                    xCoord = true;
+                }
+                continue;
+            }
+            double value = Double.parseDouble(token);
+            if (mode == 'M' || mode == 'L' || mode == 'Q' || mode == 'C' || mode == 'A') {
+                value += xCoord ? dx : dy;
+                xCoord = !xCoord;
+            }
+            if (out.length() > 0 && out.charAt(out.length() - 1) != ' ') {
+                out.append(' ');
+            }
+            out.append(oneDecimal(value));
+        }
+        return out.toString().trim();
+    }
+
+    private static boolean isDashed(char ch) {
+        return ch == '=' || ch == ':';
+    }
+
+    private static boolean isArrow(char ch) {
+        return ch == '<' || ch == '>' || ch == '^' || ch == 'v' || ch == 'V';
+    }
+
+    private static EnumSet<Dir> portsFor(Grid grid, int row, int col) {
+        char ch = grid.charAt(row, col);
+        EnumSet<Dir> ports = EnumSet.noneOf(Dir.class);
+        switch (ch) {
+            case '-':
+            case '=':
+                ports.add(Dir.LEFT);
+                ports.add(Dir.RIGHT);
+                return ports;
+            case '|':
+            case ':':
+                ports.add(Dir.UP);
+                ports.add(Dir.DOWN);
+                return ports;
+            case '>':
+                ports.add(Dir.LEFT);
+                return ports;
+            case '<':
+                ports.add(Dir.RIGHT);
+                return ports;
+            case '^':
+                ports.add(Dir.DOWN);
+                return ports;
+            case 'v':
+            case 'V':
