        }

        Options options;
        try {
            options = parseOptions(args);
        } catch (UsageException ex) {
            System.err.println("Error: " + ex.getMessage());
            System.out.print(USAGE);
            return 2;
        }

        if (options.help) {
            System.out.print(USAGE);
            return 0;
        }
        if (options.inputFile == null) {
            System.err.println("Error: Please provide the input file filename");
            System.out.print(USAGE_NOARGS);
            return 2;
        }

        if (options.html) {
            return runHtml(options);
        }

        printBanner(options);
        Path input = Paths.get(options.inputFile);
        System.out.println("Reading file: " + input);
        if (!Files.exists(input)) {
            System.err.println("Error: File " + input + " does not exist");
            return 1;
        }

        Grid grid;
        try {
            grid = Grid.fromFile(input, options.encoding, options.tabs);
        } catch (IOException ex) {
            System.err.println("Error: " + ex.getMessage());
            return 1;
        }

        if (options.debug) {
            printGrid(grid);
        }

        Path output = determineDiagramOutputPath(options, input);
        System.out.println("Rendering to file: " + output);

        Diagram diagram = Diagram.analyze(grid, options);
        if (options.svg) {
            Files.writeString(output, SvgRenderer.render(diagram, options), StandardCharsets.UTF_8);
        } else {
            PngRenderer.render(diagram, options, output);
        }
        System.out.println("Done in 0sec");
        return 0;
    }

    private int runHtml(Options options) throws Exception {
        printBanner(options);
        Path input = Paths.get(options.inputFile);
        Path processed = processedHtmlPath(input);
        if (Files.exists(processed) && !options.overwrite) {
            System.out.println(
                "Error: File " + processed +
                " exists. If you would like to overwrite it, please use the --overwrite option.");
            return 0;
        }
        String html;
        try {
            html = Files.readString(input, options.encoding);
        } catch (IOException ex) {
            System.err.println("Error: " + ex.getMessage());
            return 1;
        }

        Path imagesDir = input.getParent() == null
            ? Paths.get("images")
            : input.getParent().resolve("images");
        Files.createDirectories(imagesDir);

        System.out.print("Converting HTML file (" + input + " -> " + processed + ")... ");
        StringBuilder rewritten = new StringBuilder();
        Matcher matcher = HTML_PRE_PATTERN.matcher(html);
        int index = 0;
        int generatedIndex = 1;
        List<String> generated = new ArrayList<>();
        while (matcher.find()) {
            rewritten.append(html, index, matcher.start());
            String attrs = matcher.group(1) + " " + matcher.group(2);
            String body = matcher.group(3);
            Matcher idMatcher = ID_PATTERN.matcher(attrs);
            String baseName = idMatcher.find() ? idMatcher.group(1) : "ditaa_diagram_" + generatedIndex++;
            String ext = options.svg ? ".svg" : ".png";
            String fileName = baseName + ext;
            Path imagePath = imagesDir.resolve(fileName);
            if (!Files.exists(imagePath) || options.overwrite) {
                Grid grid = Grid.fromString(body, options.tabs);
                Diagram diagram = Diagram.analyze(grid, options);
                if (options.svg) {
                    Files.writeString(imagePath, SvgRenderer.render(diagram, options), StandardCharsets.UTF_8);
                } else {
                    PngRenderer.render(diagram, options, imagePath);
                }
                generated.add("\t" + imagePath.toString());
            }
            rewritten.append("<img src=\"images/").append(fileName).append("\" />");
            index = matcher.end();
        }
        rewritten.append(html.substring(index));
        Files.writeString(processed, rewritten.toString(), options.encoding);
        System.out.println("done");
        System.out.println("Generating diagrams... ");
        for (String line : generated) {
            System.out.println(line);
        }
        System.out.println();
        System.out.println("...done");
        return 0;
    }

    private int handleNoArgs() {
        String target = stdoutTarget();
        if (target.startsWith("pipe:[")) {
            System.err.println("Error: Please provide the input file filename");
            System.out.print(USAGE_NOARGS);
            return 2;
        }
        System.out.print(USAGE);
        return 0;
    }

    private static String stdoutTarget() {
        try {
            return Files.readSymbolicLink(Path.of("/proc/self/fd/1")).toString();
        } catch (IOException ex) {
            return "";
        }
    }

