    private static void printGrid(Grid grid) {
        System.out.println("Using grid:");
        StringBuilder header = new StringBuilder("    ");
        for (int i = 0; i <= grid.width; i++) {
            header.append(i % 10);
        }
        System.out.println(header);
        for (int row = 0; row < grid.height; row++) {
            String label = String.format(Locale.ROOT, "%2d", row);
            System.out.println(label + " (" + new String(grid.chars[row]) + ")");
        }
    }

    private static Path determineDiagramOutputPath(Options options, Path input) {
        if (options.outputFile != null) {
            return Paths.get(options.outputFile);
        }
        String ext = options.svg ? ".svg" : ".png";
        String name = input.getFileName().toString();
        int dot = name.lastIndexOf('.');
        String base = dot >= 0 ? name.substring(0, dot) : name;
        Path dir = input.getParent() == null ? Paths.get(".") : input.getParent();
        Path candidate = dir.resolve(base + ext);
        if (options.overwrite || !Files.exists(candidate)) {
            return candidate;
        }
        int counter = 2;
        while (true) {
            Path alternate = dir.resolve(base + "_" + counter + ext);
            if (!Files.exists(alternate)) {
                return alternate;
            }
            counter++;
        }
    }

    private static Path processedHtmlPath(Path input) {
        String name = input.getFileName().toString();
        int dot = name.lastIndexOf('.');
        String base = dot >= 0 ? name.substring(0, dot) : name;
        String ext = dot >= 0 ? name.substring(dot) : ".html";
        Path dir = input.getParent() == null ? Paths.get(".") : input.getParent();
        return dir.resolve(base + "_processed" + ext);
    }

    private Options parseOptions(String[] args) throws UsageException {
        Options options = new Options();
        for (int i = 0; i < args.length; i++) {
            String arg = args[i];
            if ("--help".equals(arg)) {
                options.help = true;
                options.bannerOptions.put("help", "help");
                continue;
            }
            if (arg.startsWith("--")) {
                switch (arg) {
                    case "--no-antialias":
                        options.noAntialias = true;
                        options.bannerOptions.put("no-antialias", "no-antialias");
                        continue;
                    case "--background":
                        i = parseBackground(args, i, options);
                        continue;
                    case "--debug":
                        options.debug = true;
                        options.bannerOptions.put("debug", "debug");
                        continue;
                    case "--no-separation":
                        options.noSeparation = true;
                        options.bannerOptions.put("no-separation", "no-separation");
                        continue;
                    case "--encoding":
                        i = parseEncoding(args, i, options);
                        continue;
                    case "--html":
                        options.html = true;
                        options.bannerOptions.put("html", "html");
                        continue;
                    case "--overwrite":
                        options.overwrite = true;
                        options.bannerOptions.put("overwrite", "overwrite");
                        continue;
                    case "--round-corners":
                        options.roundCorners = true;
                        options.bannerOptions.put("round-corners", "round-corners");
                        continue;
                    case "--no-shadows":
                        options.noShadows = true;
                        options.bannerOptions.put("no-shadows", "no-shadows");
                        continue;
                    case "--scale":
                        i = parseScale(args, i, options);
                        continue;
                    case "--svg":
                        options.svg = true;
                        options.bannerOptions.put("svg", "svg");
                        continue;
                    case "--svg-font-url":
                        i = parseSvgFontUrl(args, i, options);
                        continue;
                    case "--transparent":
                        options.transparent = true;
                        options.bannerOptions.put("transparent", "transparent");
                        continue;
                    case "--tabs":
                        i = parseTabs(args, i, options);
                        continue;
                    case "--verbose":
                        options.verbose = true;
                        options.bannerOptions.put("verbose", "verbose");
                        continue;
                    case "--fixed-slope":
                        options.fixedSlope = true;
                        options.bannerOptions.put("fixed-slope", "fixed-slope");
                        continue;
                    default:
                        throw new UsageException("Unrecognized option: " + arg);
                }
            }
            if (arg.startsWith("-") && arg.length() > 1) {
                switch (arg) {
                    case "-A":
                        options.noAntialias = true;
                        options.bannerOptions.put("no-antialias", "no-antialias");
                        continue;
                    case "-b":
                        i = parseBackground(args, i, options);
                        continue;
                    case "-d":
                        options.debug = true;
                        options.bannerOptions.put("debug", "debug");
                        continue;
                    case "-E":
                        options.noSeparation = true;
                        options.bannerOptions.put("no-separation", "no-separation");
                        continue;
                    case "-e":
                        i = parseEncoding(args, i, options);
                        continue;
                    case "-h":
                        options.html = true;
                        options.bannerOptions.put("html", "html");
                        continue;
                    case "-o":
                        options.overwrite = true;
                        options.bannerOptions.put("overwrite", "overwrite");
                        continue;
                    case "-r":
                        options.roundCorners = true;
                        options.bannerOptions.put("round-corners", "round-corners");
                        continue;
                    case "-S":
                        options.noShadows = true;
                        options.bannerOptions.put("no-shadows", "no-shadows");
                        continue;
                    case "-s":
                        i = parseScale(args, i, options);
                        continue;
                    case "-T":
                        options.transparent = true;
                        options.bannerOptions.put("transparent", "transparent");
                        continue;
                    case "-t":
                        i = parseTabs(args, i, options);
                        continue;
                    case "-v":
                        options.verbose = true;
                        options.bannerOptions.put("verbose", "verbose");
                        continue;
                    case "-W":
                        options.fixedSlope = true;
                        options.bannerOptions.put("fixed-slope", "fixed-slope");
                        continue;
                    default:
                        throw new UsageException("Unrecognized option: " + arg);
                }
            }

            if (options.inputFile == null) {
                options.inputFile = arg;
            } else if (options.outputFile == null) {
                options.outputFile = arg;
            } else {
                throw new UsageException("Unrecognized option: " + arg);
            }
        }
        return options;
    }

    private int parseBackground(String[] args, int index, Options options) throws UsageException {
        String value = requireValue(args, index);
        if (!value.matches("(?i)[0-9a-f]{6}([0-9a-f]{2})?")) {
            throw new UsageException(
                "Cannot interpret \"" + value + "\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).");
        }
        options.background = parseHexColor(value);
        options.backgroundRaw = value;
        options.bannerOptions.put("background", "background = " + value);
        return index + 1;
    }

    private int parseEncoding(String[] args, int index, Options options) throws UsageException {
        String value = requireValue(args, index);
        options.encoding = Charset.forName(value);
        options.bannerOptions.put("encoding", "encoding = " + value);
        return index + 1;
    }

    private int parseScale(String[] args, int index, Options options) throws UsageException {
        String value = requireValue(args, index);
        try {
            options.scale = Double.parseDouble(value);
        } catch (NumberFormatException ex) {
            throw new UsageException(ex.getMessage());
        }
        options.scaleRaw = value;
        options.bannerOptions.put("scale", "scale = " + value);
        return index + 1;
    }

    private int parseTabs(String[] args, int index, Options options) throws UsageException {
        String value = requireValue(args, index);
        try {
            options.tabs = Integer.parseInt(value);
        } catch (NumberFormatException ex) {
            throw new UsageException(ex.getMessage());
        }
        options.bannerOptions.put("tabs", "tabs = " + value);
        return index + 1;
    }

    private int parseSvgFontUrl(String[] args, int index, Options options) throws UsageException {
        String value = requireValue(args, index);
        options.svgFontUrl = value;
        options.bannerOptions.put("svg-font-url", "svg-font-url = " + value);
        return index + 1;
    }

    private static String requireValue(String[] args, int index) throws UsageException {
        if (index + 1 >= args.length) {
            throw new UsageException("Missing argument for option");
        }
        return args[index + 1];
    }

    private static Color parseHexColor(String value) {
        String hex = value.toLowerCase(Locale.ROOT);
        if (hex.length() == 6) {
            return new Color(
                Integer.parseInt(hex.substring(0, 2), 16),
                Integer.parseInt(hex.substring(2, 4), 16),
                Integer.parseInt(hex.substring(4, 6), 16));
        }
        return new Color(
            Integer.parseInt(hex.substring(0, 2), 16),
            Integer.parseInt(hex.substring(2, 4), 16),
            Integer.parseInt(hex.substring(4, 6), 16),
            Integer.parseInt(hex.substring(6, 8), 16));
    }

