    private enum Dir {
        UP(0, -1),
        RIGHT(1, 0),
        DOWN(0, 1),
        LEFT(-1, 0);

        final int dx;
        final int dy;

        Dir(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        Dir opposite() {
            switch (this) {
                case UP:
                    return DOWN;
                case RIGHT:
                    return LEFT;
                case DOWN:
                    return UP;
                default:
                    return RIGHT;
            }
        }

        int ccwOrder() {
            switch (this) {
                case RIGHT:
                    return 0;
                case UP:
                    return 1;
                case LEFT:
                    return 2;
                default:
                    return 3;
            }
        }
    }

    private static final class Grid {
        final char[][] chars;
        final int width;
        final int height;

        Grid(char[][] chars) {
            this.chars = chars;
            this.height = chars.length;
            this.width = chars.length == 0 ? 0 : chars[0].length;
        }

        static Grid fromFile(Path path, Charset charset, int tabs) throws IOException {
            return fromString(Files.readString(path, charset), tabs);
        }

        static Grid fromString(String input, int tabs) {
            String normalized = input.replace("\r\n", "\n").replace('\r', '\n');
            String[] rawLines = normalized.split("\n", -1);
            List<String> expanded = new ArrayList<>();
            int max = 0;
            int effectiveLength = rawLines.length;
            if (effectiveLength > 0 && rawLines[effectiveLength - 1].isEmpty()) {
                effectiveLength--;
            }
            for (int i = 0; i < effectiveLength; i++) {
                String line = expandTabs(rawLines[i], tabs);
                expanded.add(line);
                max = Math.max(max, line.length());
            }
            int width = max + PAD * 2;
            int height = expanded.size() + PAD * 2;
            char[][] chars = new char[height][width];
            for (char[] row : chars) {
                Arrays.fill(row, ' ');
            }
            for (int row = 0; row < expanded.size(); row++) {
                String line = expanded.get(row);
                for (int col = 0; col < line.length(); col++) {
                    chars[row + PAD][col + PAD] = line.charAt(col);
                }
            }
            return new Grid(chars);
        }

        char charAt(int row, int col) {
            if (row < 0 || row >= height || col < 0 || col >= width) {
                return ' ';
            }
            return chars[row][col];
        }

        private static String expandTabs(String line, int tabs) {
            if (tabs <= 0 || line.indexOf('\t') < 0) {
                return line;
            }
            StringBuilder builder = new StringBuilder();
            int column = 0;
            for (int i = 0; i < line.length(); i++) {
                char ch = line.charAt(i);
                if (ch == '\t') {
                    int spaces = tabs - (column % tabs);
                    for (int j = 0; j < spaces; j++) {
                        builder.append(' ');
                        column++;
                    }
                } else {
                    builder.append(ch);
                    column++;
                }
            }
            return builder.toString();
        }
    }

    private static final class Diagram {
        final Grid grid;
        final List<ShapeRegion> shapes;
        final List<LinePath> lines;
        final List<TextItem> freeText;
        final List<Marker> markers;

        Diagram(Grid grid, List<ShapeRegion> shapes, List<LinePath> lines,
                List<TextItem> freeText, List<Marker> markers) {
            this.grid = grid;
            this.shapes = shapes;
            this.lines = lines;
            this.freeText = freeText;
            this.markers = markers;
        }

        static Diagram analyze(Grid grid, Options options) {
            Graph graph = Graph.build(grid);
            List<Face> faces = graph.findFaces();
            List<ShapeRegion> shapes = new ArrayList<>();
            for (Face face : faces) {
                shapes.add(ShapeRegion.fromFace(face, grid, options));
            }
            shapes.sort(Comparator.comparingDouble((ShapeRegion s) -> -Math.abs(s.face.area)));

            Set<Edge> shapeEdges = new HashSet<>();
            for (ShapeRegion shape : shapes) {
                shapeEdges.addAll(shape.face.edges);
            }

            List<LinePath> lines = graph.findOpenLines(shapeEdges, options);
            List<Marker> markers = graph.findMarkers();
            List<TextItem> freeText = collectFreeText(grid, shapes, graph);
            return new Diagram(grid, shapes, lines, freeText, markers);
        }

        private static List<TextItem> collectFreeText(Grid grid, List<ShapeRegion> shapes, Graph graph) {
            List<TextItem> items = new ArrayList<>();
            boolean[][] insideShape = new boolean[grid.height][grid.width];
            for (ShapeRegion shape : shapes) {
                for (int row = shape.minRow; row <= shape.maxRow; row++) {
                    for (int col = shape.minCol; col <= shape.maxCol; col++) {
                        if (shape.contains(col, row)) {
                            insideShape[row][col] = true;
                        }
                    }
                }
            }

            for (int row = 0; row < grid.height; row++) {
                int col = 0;
                while (col < grid.width) {
                    if (insideShape[row][col] || graph.isLineGlyph(row, col)) {
                        col++;
                        continue;
                    }
                    char ch = grid.charAt(row, col);
                    if (ch == ' ') {
                        col++;
                        continue;
                    }
                    int start = col;
                    StringBuilder text = new StringBuilder();
                    while (col < grid.width && !insideShape[row][col] && !graph.isLineGlyph(row, col)) {
                        char curr = grid.charAt(row, col);
                        if (curr == ' ') {
                            break;
                        }
                        text.append(curr);
                        col++;
                    }
                    if (text.length() > 0) {
                        items.add(new TextItem(text.toString(), start, row, null, false));
                    } else {
                        col++;
                    }
                }
            }
            return items;
        }
    }

    private static final class Graph {
        final Grid grid;
        final Node[][] nodes;
        final List<Node> nodeList;
        final List<Edge> edges;

        Graph(Grid grid, Node[][] nodes, List<Node> nodeList, List<Edge> edges) {
            this.grid = grid;
            this.nodes = nodes;
            this.nodeList = nodeList;
            this.edges = edges;
        }

        static Graph build(Grid grid) {
            Node[][] nodes = new Node[grid.height][grid.width];
            List<Node> nodeList = new ArrayList<>();
            for (int row = 0; row < grid.height; row++) {
                for (int col = 0; col < grid.width; col++) {
                    EnumSet<Dir> ports = portsFor(grid, row, col);
                    if (!ports.isEmpty()) {
                        Node node = new Node(row, col, grid.charAt(row, col), ports);
                        nodes[row][col] = node;
                        nodeList.add(node);
                    }
                }
            }
            List<Edge> edges = new ArrayList<>();
            for (int row = 0; row < grid.height; row++) {
                for (int col = 0; col < grid.width; col++) {
                    Node node = nodes[row][col];
                    if (node == null) {
                        continue;
                    }
                    if (node.ports.contains(Dir.RIGHT) && col + 1 < grid.width) {
                        Node other = nodes[row][col + 1];
                        if (other != null && other.ports.contains(Dir.LEFT)) {
                            Edge edge = new Edge(node, other, isDashed(grid.charAt(row, col)) || isDashed(grid.charAt(row, col + 1)));
                            node.edges.add(edge);
                            other.edges.add(edge);
                            edges.add(edge);
                        }
                    }
                    if (node.ports.contains(Dir.DOWN) && row + 1 < grid.height) {
                        Node other = nodes[row + 1][col];
                        if (other != null && other.ports.contains(Dir.UP)) {
                            Edge edge = new Edge(node, other, isDashed(grid.charAt(row, col)) || isDashed(grid.charAt(row + 1, col)));
                            node.edges.add(edge);
                            other.edges.add(edge);
                            edges.add(edge);
                        }
                    }
                }
            }
            for (Node node : nodeList) {
                node.prepareHalfEdges();
            }
            return new Graph(grid, nodes, nodeList, edges);
        }

        boolean isLineGlyph(int row, int col) {
            return nodes[row][col] != null;
        }

        List<Face> findFaces() {
            List<Face> faces = new ArrayList<>();
            for (Node node : nodeList) {
                for (HalfEdge start : node.outgoing) {
                    if (start.scanned) {
                        continue;
                    }
                    Face face = traceFace(start);
                    if (face != null && face.area > 0.0) {
                        faces.add(face);
                    }
                }
            }
            return faces;
        }

        private Face traceFace(HalfEdge start) {
            List<HalfEdge> walked = new ArrayList<>();
            List<Node> polygon = new ArrayList<>();
            HalfEdge edge = start;
            while (true) {
                if (edge.tempSeen) {
                    for (HalfEdge part : walked) {
                        part.scanned = true;
                        part.tempSeen = false;
                    }
                    return null;
                }
                edge.tempSeen = true;
                walked.add(edge);
                polygon.add(edge.from);
                List<HalfEdge> outgoing = edge.to.outgoing;
                if (outgoing.size() <= 1) {
                    for (HalfEdge part : walked) {
                        part.scanned = true;
                        part.tempSeen = false;
                    }
                    return null;
                }
                int reverseIndex = outgoing.indexOf(edge.twin);
                if (reverseIndex < 0) {
                    for (HalfEdge part : walked) {
                        part.scanned = true;
                        part.tempSeen = false;
                    }
                    return null;
                }
                HalfEdge next = outgoing.get((reverseIndex + 1) % outgoing.size());
                if (next == start) {
                    break;
                }
                edge = next;
            }
            Set<Edge> faceEdges = new HashSet<>();
            for (HalfEdge part : walked) {
                part.scanned = true;
                part.tempSeen = false;
                faceEdges.add(part.edge);
            }
            List<Node> simplified = simplifyPolygon(polygon);
            double area = polygonArea(simplified);
            return new Face(simplified, area, faceEdges);
        }

        List<LinePath> findOpenLines(Set<Edge> shapeEdges, Options options) {
            Map<Node, List<Edge>> remaining = new HashMap<>();
            for (Edge edge : edges) {
                if (shapeEdges.contains(edge)) {
                    continue;
                }
                remaining.computeIfAbsent(edge.a, key -> new ArrayList<>()).add(edge);
                remaining.computeIfAbsent(edge.b, key -> new ArrayList<>()).add(edge);
            }
            Set<Edge> visited = new HashSet<>();
            List<LinePath> lines = new ArrayList<>();
            for (Map.Entry<Node, List<Edge>> entry : remaining.entrySet()) {
                Node start = entry.getKey();
                int degree = entry.getValue().size();
                if (degree == 2) {
                    continue;
                }
                for (Edge edge : entry.getValue()) {
                    if (visited.contains(edge)) {
                        continue;
                    }
                    lines.add(traceLine(start, edge, remaining, visited, options));
                }
            }
            for (Edge edge : edges) {
                if (shapeEdges.contains(edge) || visited.contains(edge)) {
                    continue;
                }
                lines.add(traceCycle(edge, remaining, visited, options));
            }
            return lines;
        }

        private LinePath traceLine(Node start, Edge first, Map<Node, List<Edge>> remaining,
                                   Set<Edge> visited, Options options) {
            List<Node> nodes = new ArrayList<>();
            List<Edge> usedEdges = new ArrayList<>();
            Node current = start;
            Edge edge = first;
            while (edge != null) {
                nodes.add(current);
                visited.add(edge);
                usedEdges.add(edge);
                Node next = edge.other(current);
                current = next;
                List<Edge> incident = remaining.getOrDefault(current, Collections.emptyList());
                Edge nextEdge = null;
                if (incident.size() == 2) {
                    for (Edge candidate : incident) {
                        if (!visited.contains(candidate) && candidate != edge) {
                            nextEdge = candidate;
                            break;
                        }
                    }
                }
                if (nextEdge == null) {
                    nodes.add(current);
                    break;
                }
                edge = nextEdge;
            }
            return new LinePath(nodes, usedEdges, options.roundCorners);
        }

        private LinePath traceCycle(Edge start, Map<Node, List<Edge>> remaining,
                                    Set<Edge> visited, Options options) {
            List<Node> nodes = new ArrayList<>();
            List<Edge> usedEdges = new ArrayList<>();
            Node current = start.a;
            Edge edge = start;
            Node cycleStart = current;
            while (true) {
                nodes.add(current);
                visited.add(edge);
                usedEdges.add(edge);
                Node next = edge.other(current);
                current = next;
                if (current == cycleStart) {
                    nodes.add(current);
                    break;
                }
                List<Edge> incident = remaining.getOrDefault(current, Collections.emptyList());
                Edge nextEdge = null;
                for (Edge candidate : incident) {
                    if (!visited.contains(candidate)) {
                        nextEdge = candidate;
                        break;
                    }
                }
                if (nextEdge == null) {
                    nodes.add(current);
                    break;
                }
                edge = nextEdge;
            }
            return new LinePath(nodes, usedEdges, options.roundCorners);
        }

        List<Marker> findMarkers() {
            List<Marker> markers = new ArrayList<>();
            for (Node node : nodeList) {
                if (node.ch == '*') {
                    markers.add(new Marker(node.col, node.row));
                }
            }
            return markers;
        }
    }

    private static final class Node {
        final int row;
        final int col;
        final char ch;
        final EnumSet<Dir> ports;
        final List<Edge> edges = new ArrayList<>();
        final List<HalfEdge> outgoing = new ArrayList<>();

        Node(int row, int col, char ch, EnumSet<Dir> ports) {
            this.row = row;
            this.col = col;
            this.ch = ch;
            this.ports = ports;
        }

        void prepareHalfEdges() {
            outgoing.clear();
            for (Edge edge : edges) {
                outgoing.add(edge.from(this));
            }
            outgoing.sort(Comparator.comparingInt(halfEdge -> directionOf(halfEdge).ccwOrder()));
        }

        private Dir directionOf(HalfEdge edge) {
            Node other = edge.to;
            if (other.col > col) {
                return Dir.RIGHT;
            }
            if (other.col < col) {
                return Dir.LEFT;
            }
            if (other.row < row) {
                return Dir.UP;
            }
            return Dir.DOWN;
        }
    }

    private static final class Edge {
        final Node a;
        final Node b;
        final boolean dashed;
        final HalfEdge ab;
        final HalfEdge ba;

        Edge(Node a, Node b, boolean dashed) {
            this.a = a;
            this.b = b;
            this.dashed = dashed;
            this.ab = new HalfEdge(this, a, b);
            this.ba = new HalfEdge(this, b, a);
            this.ab.twin = this.ba;
            this.ba.twin = this.ab;
        }

        HalfEdge from(Node node) {
            return node == a ? ab : ba;
        }

        Node other(Node node) {
            return node == a ? b : a;
        }
    }

    private static final class HalfEdge {
        final Edge edge;
        final Node from;
        final Node to;
        HalfEdge twin;
        boolean scanned;
        boolean tempSeen;

        HalfEdge(Edge edge, Node from, Node to) {
            this.edge = edge;
            this.from = from;
            this.to = to;
        }
    }

    private static final class Face {
        final List<Node> polygon;
