    private static final class SvgRenderer {
        static String render(Diagram diagram, Options options) {
            int width = scaledValue(diagram.grid.width * CELL_W, options.scale);
            int height = scaledValue(diagram.grid.height * CELL_H, options.scale);
            StringBuilder out = new StringBuilder();
            out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n");
            out.append("<svg \n");
            out.append("    xmlns='http://www.w3.org/2000/svg'\n");
            out.append("    width='").append(width).append("'\n");
            out.append("    height='").append(height).append("'\n");
            out.append("    shape-rendering='geometricPrecision'\n");
            out.append("    version='1.0'>\n");
            out.append("  <defs>\n");
            if (options.svgFontUrl != null) {
                out.append("    <style type='text/css'>\n");
                out.append("      @font-face {\n");
                out.append("        font-family: Custom;\n");
                out.append("        src: url('").append(escapeXml(options.svgFontUrl)).append("');\n");
                out.append("      }\n");
                out.append("    </style>\n");
            }
            out.append("    <filter id='f2' x='0' y='0' width='200%' height='200%'>\n");
            out.append("      <feOffset result='offOut' in='SourceGraphic' dx='5' dy='5' />\n");
            out.append("      <feGaussianBlur result='blurOut' in='offOut' stdDeviation='3' />\n");
            out.append("      <feBlend in='SourceGraphic' in2='blurOut' mode='normal' />\n");
            out.append("    </filter>\n");
            out.append("  </defs>\n");
            out.append("  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round'>\n");
            if (!options.transparent) {
                out.append("    <rect x='0' y='0' width='").append(width).append("' height='").append(height)
                    .append("' style='fill: ").append(colorToSvg(options.background, false)).append("'/>\n");
            }
            for (ShapeRegion shape : diagram.shapes) {
                ShapeGeometry geometry = ShapeGeometry.forShape(shape, options);
                if (!options.noShadows) {
                    out.append("    <path stroke='gray' fill='gray' filter='url(#f2)' d='")
                        .append(geometry.shadowPathSvg).append("' />\n");
                }
                if (!options.noSeparation) {
                    out.append("    <path stroke='white' stroke-width='3.0' stroke-linecap='round' stroke-linejoin='round' fill='none' d='")
                        .append(geometry.outlineSvg).append("' />\n");
                }
                if (shape.kind == ShapeKind.STORAGE) {
                    out.append("    <path stroke='").append(colorToSvg(shape.fill, false))
                        .append("' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='")
                        .append(colorToSvg(shape.fill, false)).append("' d='")
                        .append(geometry.fillSvg).append("' />\n");
                    out.append("    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='none' d='")
                        .append(geometry.outlineSvg).append("' />\n");
                } else {
                    out.append("    <path stroke='#000000' stroke-width='")
                        .append(oneDecimal(options.scale)).append("' stroke-linecap='round' stroke-linejoin='round' fill='")
                        .append(colorToSvg(shape.fill, false)).append("' d='")
                        .append(geometry.fillSvg).append("' />\n");
                }
                for (String extra : geometry.extraSvg) {
                    out.append("    ").append(extra).append('\n');
                }
                for (TextItem text : shape.text) {
                    if (text.text.isEmpty()) {
                        continue;
                    }
                    int fontSize = fitFontSize(text.text, text.col, text.row, shape, options.scale);
                    int x = textStartX(text.col, options.scale);
                    int y = textBaselineY(text.row, options.scale);
                    out.append("    <text x='").append(x).append("' y='").append(y)
                        .append("' font-family='").append(options.svgFontUrl == null ? "Courier" : "Custom")
                        .append("' font-size='").append(fontSize)
                        .append("' stroke='none' fill='").append(colorToSvg(shape.textColor, false))
                        .append("' ><![CDATA[").append(escapeCdata(text.text)).append("]]></text>\n");
                }
            }
            for (LinePath line : diagram.lines) {
                ShapeGeometry geometry = ShapeGeometry.forLine(line, options);
                out.append("    <path stroke='#000000' stroke-width='").append(oneDecimal(options.scale)).append("'");
                if (line.dashed) {
                    double dash = 5.0 * options.scale;
                    out.append(" stroke-dasharray='").append(oneDecimal(dash)).append(',').append(oneDecimal(dash))
                        .append("' stroke-miterlimit='0' stroke-linecap='butt'");
                } else {
                    out.append(" stroke-linecap='round'");
                }
                out.append(" stroke-linejoin='round' fill='none' d='").append(geometry.outlineSvg).append("' />\n");
                for (String extra : geometry.extraSvg) {
                    out.append("    ").append(extra).append('\n');
                }
            }
            for (TextItem item : diagram.freeText) {
                out.append("    <text x='").append(textStartX(item.col, options.scale)).append("' y='")
                    .append(textBaselineY(item.row, options.scale))
                    .append("' font-family='").append(options.svgFontUrl == null ? "Courier" : "Custom")
                    .append("' font-size='").append(scaledValue(15, options.scale))
                    .append("' stroke='none' fill='#000000' ><![CDATA[")
                    .append(escapeCdata(item.text)).append("]]></text>\n");
            }
            for (Marker marker : diagram.markers) {
                double cx = coordX(marker.col, options.scale);
                double cy = coordY(marker.row, options.scale);
                double r = 3.5 * options.scale;
                out.append("    <path stroke='#000000' stroke-width='").append(oneDecimal(options.scale))
                    .append("' stroke-linecap='round' stroke-linejoin='round' fill='#ffffff' d='")
                    .append(circlePath(cx, cy, r)).append("' />\n");
            }
            out.append("  </g>\n");
            out.append("</svg>\n");
            return out.toString();
        }
    }

    private static final class PngRenderer {
        static void render(Diagram diagram, Options options, Path output) throws IOException {
            int width = scaledValue(diagram.grid.width * CELL_W, options.scale);
            int height = scaledValue(diagram.grid.height * CELL_H, options.scale);
            boolean alpha = options.transparent || options.background.getAlpha() < 255;
            BufferedImage image = new BufferedImage(width, height, alpha ? BufferedImage.TYPE_INT_ARGB : BufferedImage.TYPE_INT_RGB);
            Graphics2D graphics = image.createGraphics();
            setHints(graphics, options);
            if (!options.transparent) {
                graphics.setColor(options.background);
                graphics.fillRect(0, 0, width, height);
            }
            if (options.debug) {
                graphics.setColor(new Color(0xcc, 0xcc, 0xcc));
                for (int x = 0; x <= width; x += scaledValue(CELL_W, options.scale)) {
                    graphics.drawLine(x, 0, x, height);
                }
                for (int y = 0; y <= height; y += scaledValue(CELL_H, options.scale)) {
                    graphics.drawLine(0, y, width, y);
                }
            }

            if (!options.noShadows) {
                BufferedImage shadow = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
                Graphics2D shadowGraphics = shadow.createGraphics();
                setHints(shadowGraphics, options);
                shadowGraphics.setComposite(AlphaComposite.SrcOver);
                shadowGraphics.setColor(new Color(128, 128, 128, 180));
                for (ShapeRegion shape : diagram.shapes) {
                    ShapeGeometry geometry = ShapeGeometry.forShape(shape, options);
                    shadowGraphics.fill(geometry.shadowPath);
                }
                shadowGraphics.dispose();
                shadow = blur(shadow, Math.max(1, (int) Math.round(3 * options.scale)));
                graphics.drawImage(shadow, 0, 0, null);
            }

            for (ShapeRegion shape : diagram.shapes) {
                ShapeGeometry geometry = ShapeGeometry.forShape(shape, options);
                if (!options.noSeparation) {
                    graphics.setColor(Color.WHITE);
                    graphics.setStroke(new BasicStroke((float) Math.max(1.0, 3.0 * options.scale),
                        BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                    graphics.draw(geometry.outlinePath);
                }
                graphics.setColor(shape.fill);
                graphics.fill(geometry.fillPath);
                graphics.setColor(Color.BLACK);
                graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
                    BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                graphics.draw(geometry.outlinePath);
                for (Path2D extra : geometry.extraPaths) {
                    graphics.draw(extra);
                }
                for (TextItem text : shape.text) {
                    if (text.text.isEmpty()) {
                        continue;
                    }
                    int fontSize = fitFontSize(text.text, text.col, text.row, shape, options.scale);
                    Font font = new Font("Courier", Font.BOLD, fontSize);
                    graphics.setFont(font);
                    graphics.setColor(shape.textColor);
                    graphics.drawString(text.text, textStartX(text.col, options.scale), textBaselineY(text.row, options.scale));
                }
            }

            graphics.setColor(Color.BLACK);
            for (LinePath line : diagram.lines) {
                ShapeGeometry geometry = ShapeGeometry.forLine(line, options);
                if (line.dashed) {
                    float dash = (float) Math.max(1.0, 5.0 * options.scale);
                    graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
                        BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 10f, new float[] {dash, dash}, 0f));
                } else {
                    graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
                        BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                }
                graphics.draw(geometry.outlinePath);
                for (Path2D extra : geometry.extraPaths) {
                    graphics.fill(extra);
                }
            }

            graphics.setStroke(new BasicStroke((float) Math.max(1.0, options.scale),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            graphics.setFont(new Font("Courier", Font.BOLD, scaledValue(15, options.scale)));
            for (TextItem item : diagram.freeText) {
                graphics.setColor(Color.BLACK);
                graphics.drawString(item.text, textStartX(item.col, options.scale), textBaselineY(item.row, options.scale));
            }
            for (Marker marker : diagram.markers) {
                double cx = coordX(marker.col, options.scale);
                double cy = coordY(marker.row, options.scale);
                double r = 3.5 * options.scale;
                graphics.setColor(Color.WHITE);
                graphics.fill(new Ellipse2D.Double(cx - r, cy - r, r * 2.0, r * 2.0));
                graphics.setColor(Color.BLACK);
                graphics.draw(new Ellipse2D.Double(cx - r, cy - r, r * 2.0, r * 2.0));
            }
            graphics.dispose();

            try (OutputStream stream = Files.newOutputStream(output)) {
                ImageIO.write(image, "png", stream);
            }
        }

        private static void setHints(Graphics2D graphics, Options options) {
            Object aa = options.noAntialias
                ? RenderingHints.VALUE_ANTIALIAS_OFF
                : RenderingHints.VALUE_ANTIALIAS_ON;
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
            graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, aa);
            graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
            graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        }
    }

    private static final class ShapeGeometry {
        final Path2D fillPath;
        final Path2D outlinePath;
        final Path2D shadowPath;
        final String fillSvg;
        final String outlineSvg;
        final String shadowPathSvg;
        final List<Path2D> extraPaths;
        final List<String> extraSvg;

        ShapeGeometry(Path2D fillPath, Path2D outlinePath, Path2D shadowPath,
                      String fillSvg, String outlineSvg, String shadowPathSvg,
                      List<Path2D> extraPaths, List<String> extraSvg) {
            this.fillPath = fillPath;
            this.outlinePath = outlinePath;
            this.shadowPath = shadowPath;
            this.fillSvg = fillSvg;
            this.outlineSvg = outlineSvg;
            this.shadowPathSvg = shadowPathSvg;
            this.extraPaths = extraPaths;
            this.extraSvg = extraSvg;
        }

        static ShapeGeometry forShape(ShapeRegion shape, Options options) {
            Rect rect = boundingRect(shape.face.polygon, options.scale);
            switch (shape.kind) {
                case DOCUMENT:
                    return document(rect, options);
                case STORAGE:
                    return storage(rect, options);
                case ELLIPSE:
                    return ellipse(rect, options);
                case CHOICE:
                    return choice(rect, options);
                case IO:
                    return io(rect, options, 5.0 * options.scale);
                case IO_FIXED:
                    return io(rect, options, 5.25 * options.scale);
                case TRAPEZOID:
                    return trapezoid(rect, options, 5.0 * options.scale, true);
                case TRAPEZOID_FIXED:
                    return trapezoid(rect, options, 5.25 * options.scale, true);
                case MANUAL_OPERATION:
                    return trapezoid(rect, options, 5.0 * options.scale, false);
                default:
                    return polygon(shape.face.polygon, shape.roundCorners, options);
            }
        }

        static ShapeGeometry forLine(LinePath line, Options options) {
            PathResult outline = buildLinePath(line.nodes, line.roundCorners, options);
            List<Path2D> extras = new ArrayList<>();
            List<String> extraSvg = new ArrayList<>();
            addArrow(line.nodes, options, extras, extraSvg);
            return new ShapeGeometry(outline.path, outline.path, outline.path,
                outline.svg, outline.svg, outline.svg, extras, extraSvg);
        }

        private static ShapeGeometry polygon(List<Node> polygon, boolean roundCorners, Options options) {
            PathResult result = buildPolygonPath(polygon, roundCorners, options);
            Path2D shadowPath = translate(result.path, 5.0 * options.scale, 5.0 * options.scale);
            String shadowSvg = translateSvg(result.svg, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(result.path, result.path, shadowPath, result.svg, result.svg, shadowSvg,
                new ArrayList<>(), new ArrayList<>());
        }

        private static ShapeGeometry document(Rect rect, Options options) {
            Path2D path = new Path2D.Double();
            path.moveTo(rect.left, rect.top);
            path.lineTo(rect.right, rect.top);
            path.lineTo(rect.right, rect.bottom);
            double cp1x = rect.right - (rect.width() / 3.0);
            double cp2x = rect.left + (rect.width() / 3.0);
            double midx = rect.left + rect.width() / 2.0;
            path.quadTo(cp1x, rect.bottom - 8.0 * options.scale, midx, rect.bottom);
            path.quadTo(cp2x, rect.bottom + 8.0 * options.scale, rect.left, rect.bottom);
            path.closePath();
            String svg = "M" + oneDecimal(rect.left) + " " + oneDecimal(rect.top) +
                " L" + oneDecimal(rect.right) + " " + oneDecimal(rect.top) +
                " L" + oneDecimal(rect.right) + " " + oneDecimal(rect.bottom) +
                " Q" + oneDecimal(cp1x) + " " + oneDecimal(rect.bottom - 8.0 * options.scale) +
                " " + oneDecimal(midx) + " " + oneDecimal(rect.bottom) +
                " Q" + oneDecimal(cp2x) + " " + oneDecimal(rect.bottom + 8.0 * options.scale) +
                " " + oneDecimal(rect.left) + " " + oneDecimal(rect.bottom) + " z";
            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
                new ArrayList<>(), new ArrayList<>());
        }

        private static ShapeGeometry storage(Rect rect, Options options) {
            double ctrl = rect.width() / 6.0;
            double ry = 7.0 * options.scale;
            Path2D fill = new Path2D.Double();
            fill.moveTo(rect.left, rect.top);
            fill.curveTo(rect.left + ctrl, rect.top + ry, rect.right - ctrl, rect.top + ry, rect.right, rect.top);
            fill.lineTo(rect.right, rect.bottom);
            fill.curveTo(rect.right - ctrl, rect.bottom + 10.0 * options.scale, rect.left + ctrl, rect.bottom + 10.0 * options.scale, rect.left, rect.bottom);
            fill.closePath();

            Path2D outline = new Path2D.Double();
            outline.moveTo(rect.left, rect.top);
            outline.curveTo(rect.left + ctrl, rect.top + ry, rect.right - ctrl, rect.top + ry, rect.right, rect.top);
            outline.curveTo(rect.right - ctrl, rect.top - ry, rect.left + ctrl, rect.top - ry, rect.left, rect.top);
            outline.moveTo(rect.left, rect.top);
            outline.lineTo(rect.left, rect.bottom);
            outline.curveTo(rect.left + ctrl, rect.bottom + 10.0 * options.scale, rect.right - ctrl, rect.bottom + 10.0 * options.scale, rect.right, rect.bottom);
            outline.lineTo(rect.right, rect.top);

            String fillSvg = pathToSvg(fill);
            String outlineSvg = pathToSvg(outline);
            Path2D shadow = translate(outline, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(fill, outline, shadow, fillSvg, outlineSvg,
                translateSvg(outlineSvg, 5.0 * options.scale, 5.0 * options.scale),
                new ArrayList<>(), new ArrayList<>());
        }

        private static ShapeGeometry ellipse(Rect rect, Options options) {
            Path2D path = new Path2D.Double();
            path.moveTo(rect.centerX(), rect.top);
            path.curveTo(rect.right, rect.top, rect.right, rect.centerY(), rect.right, rect.centerY());
            path.curveTo(rect.right, rect.bottom, rect.centerX(), rect.bottom, rect.centerX(), rect.bottom);
            path.curveTo(rect.left, rect.bottom, rect.left, rect.centerY(), rect.left, rect.centerY());
            path.curveTo(rect.left, rect.top, rect.centerX(), rect.top, rect.centerX(), rect.top);
            path.closePath();
            String svg = pathToSvg(path);
            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
                new ArrayList<>(), new ArrayList<>());
        }

        private static ShapeGeometry choice(Rect rect, Options options) {
            Path2D path = new Path2D.Double();
            path.moveTo(rect.left, rect.centerY());
            path.lineTo(rect.centerX(), rect.top);
            path.lineTo(rect.right, rect.centerY());
            path.lineTo(rect.centerX(), rect.bottom);
            path.closePath();
            String svg = pathToSvg(path);
            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
                new ArrayList<>(), new ArrayList<>());
        }

        private static ShapeGeometry io(Rect rect, Options options, double dx) {
            Path2D path = new Path2D.Double();
            path.moveTo(rect.left + dx, rect.top);
            path.lineTo(rect.right + dx, rect.top);
            path.lineTo(rect.right - dx, rect.bottom);
            path.lineTo(rect.left - dx, rect.bottom);
            path.closePath();
            String svg = pathToSvg(path);
            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
                new ArrayList<>(), new ArrayList<>());
        }

        private static ShapeGeometry trapezoid(Rect rect, Options options, double dx, boolean topNarrow) {
            Path2D path = new Path2D.Double();
            if (topNarrow) {
                path.moveTo(rect.left + dx, rect.top);
                path.lineTo(rect.right - dx, rect.top);
                path.lineTo(rect.right + dx, rect.bottom);
                path.lineTo(rect.left - dx, rect.bottom);
            } else {
                path.moveTo(rect.left - dx, rect.top);
                path.lineTo(rect.right + dx, rect.top);
                path.lineTo(rect.right - dx, rect.bottom);
                path.lineTo(rect.left + dx, rect.bottom);
            }
            path.closePath();
            String svg = pathToSvg(path);
            Path2D shadow = translate(path, 5.0 * options.scale, 5.0 * options.scale);
            return new ShapeGeometry(path, path, shadow, svg, svg, translateSvg(svg, 5.0 * options.scale, 5.0 * options.scale),
                new ArrayList<>(), new ArrayList<>());
        }

        private static void addArrow(List<Node> nodes, Options options, List<Path2D> extras, List<String> extraSvg) {
            if (nodes.isEmpty()) {
                return;
            }
            Node first = nodes.get(0);
            Node last = nodes.get(nodes.size() - 1);
            if (isArrow(first.ch)) {
                Path2D path = arrowPath(first.ch, coordX(first.col, options.scale), coordY(first.row, options.scale), options.scale);
                extras.add(path);
                extraSvg.add("<path stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='" + pathToSvg(path) + "' />");
            }
            if (isArrow(last.ch)) {
                Path2D path = arrowPath(last.ch, coordX(last.col, options.scale), coordY(last.row, options.scale), options.scale);
                extras.add(path);
                extraSvg.add("<path stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='" + pathToSvg(path) + "' />");
            }
        }
    }

    private static final class PathResult {
        final Path2D path;
        final String svg;

        PathResult(Path2D path, String svg) {
            this.path = path;
            this.svg = svg;
        }
    }

    private static PathResult buildPolygonPath(List<Node> polygon, boolean roundCorners, Options options) {
        List<Point2D.Double> points = new ArrayList<>();
        List<Boolean> rounded = new ArrayList<>();
        for (Node node : polygon) {
            points.add(new Point2D.Double(coordX(node.col, options.scale), coordY(node.row, options.scale)));
            rounded.add(roundCorners || node.ch == '/' || node.ch == '\\');
        }
        return buildPath(points, rounded, true);
    }

    private static PathResult buildLinePath(List<Node> nodes, boolean roundCorners, Options options) {
        List<Point2D.Double> points = new ArrayList<>();
        List<Boolean> rounded = new ArrayList<>();
        for (Node node : nodes) {
            points.add(new Point2D.Double(coordX(node.col, options.scale), coordY(node.row, options.scale)));
            rounded.add(roundCorners || node.ch == '/' || node.ch == '\\');
        }
        return buildPath(points, rounded, false);
    }

    private static PathResult buildPath(List<Point2D.Double> points, List<Boolean> rounded, boolean closed) {
        Path2D path = new Path2D.Double();
        StringBuilder svg = new StringBuilder();
        int n = points.size();
        if (n == 0) {
            return new PathResult(path, "");
        }
        if (closed && !points.isEmpty() && points.get(0).equals(points.get(n - 1))) {
            points = new ArrayList<>(points.subList(0, n - 1));
            rounded = new ArrayList<>(rounded.subList(0, n - 1));
            n = points.size();
        }
        if (n == 0) {
            return new PathResult(path, "");
        }
        Point2D.Double start = points.get(0);
        path.moveTo(start.x, start.y);
        svg.append("M").append(oneDecimal(start.x)).append(" ").append(oneDecimal(start.y));
        for (int i = 1; i < n; i++) {
            Point2D.Double curr = points.get(i);
            if (rounded.get(i) && i > 0 && i < n - 1) {
                Point2D.Double prev = points.get(i - 1);
                Point2D.Double next = points.get(i + 1);
                Point2D.Double before = offsetTowards(curr, prev);
                Point2D.Double after = offsetTowards(curr, next);
                path.lineTo(before.x, before.y);
                path.quadTo(curr.x, curr.y, after.x, after.y);
                svg.append(" L").append(oneDecimal(before.x)).append(" ").append(oneDecimal(before.y))
                    .append(" Q").append(oneDecimal(curr.x)).append(" ").append(oneDecimal(curr.y))
                    .append(" ").append(oneDecimal(after.x)).append(" ").append(oneDecimal(after.y));
            } else {
                path.lineTo(curr.x, curr.y);
                svg.append(" L").append(oneDecimal(curr.x)).append(" ").append(oneDecimal(curr.y));
            }
        }
        if (closed) {
            path.closePath();
            svg.append(" z");
        }
        return new PathResult(path, svg.toString());
    }

    private static Point2D.Double offsetTowards(Point2D.Double from, Point2D.Double to) {
        double dx = to.x - from.x;
        double dy = to.y - from.y;
        if (Math.abs(dx) > Math.abs(dy)) {
            return new Point2D.Double(from.x + Math.signum(dx) * 5.0, from.y);
        }
        return new Point2D.Double(from.x, from.y + Math.signum(dy) * 7.0);
    }

    private static Path2D translate(Path2D path, double dx, double dy) {
        Path2D copy = (Path2D) path.clone();
        copy.transform(java.awt.geom.AffineTransform.getTranslateInstance(dx, dy));
        return copy;
    }

    private static String translateSvg(String svg, double dx, double dy) {
        StringBuilder out = new StringBuilder();
        Matcher matcher = Pattern.compile("([MLQCA])|(-?\\d+(?:\\.\\d+)?)").matcher(svg);
        List<String> tokens = new ArrayList<>();
        while (matcher.find()) {
            tokens.add(matcher.group());
        }
        boolean xCoord = false;
        char mode = ' ';
        for (String token : tokens) {
            if (token.length() == 1 && Character.isLetter(token.charAt(0))) {
                mode = token.charAt(0);
                out.append(token);
                if (mode == 'z' || mode == 'Z') {
                    xCoord = false;
                } else {
                    xCoord = true;
                }
                continue;
            }
            double value = Double.parseDouble(token);
            if (mode == 'M' || mode == 'L' || mode == 'Q' || mode == 'C' || mode == 'A') {
                value += xCoord ? dx : dy;
                xCoord = !xCoord;
            }
            if (out.length() > 0 && out.charAt(out.length() - 1) != ' ') {
                out.append(' ');
            }
            out.append(oneDecimal(value));
        }
        return out.toString().trim();
    }

    private static boolean isDashed(char ch) {
        return ch == '=' || ch == ':';
    }

    private static boolean isArrow(char ch) {
        return ch == '<' || ch == '>' || ch == '^' || ch == 'v' || ch == 'V';
    }

    private static EnumSet<Dir> portsFor(Grid grid, int row, int col) {
        char ch = grid.charAt(row, col);
        EnumSet<Dir> ports = EnumSet.noneOf(Dir.class);
        switch (ch) {
            case '-':
            case '=':
                ports.add(Dir.LEFT);
                ports.add(Dir.RIGHT);
                return ports;
            case '|':
            case ':':
                ports.add(Dir.UP);
                ports.add(Dir.DOWN);
                return ports;
            case '>':
                ports.add(Dir.LEFT);
                return ports;
            case '<':
                ports.add(Dir.RIGHT);
                return ports;
            case '^':
                ports.add(Dir.DOWN);
                return ports;
            case 'v':
            case 'V':
                ports.add(Dir.UP);
                return ports;
            case '+':
            case '*':
                for (Dir dir : Dir.values()) {
                    if (neighborSupports(grid, row, col, dir)) {
                        ports.add(dir);
                    }
                }
                return ports;
            case '/':
                return slashPorts(grid, row, col);
            case '\\':
                return backslashPorts(grid, row, col);
            default:
                return ports;
        }
    }

    private static EnumSet<Dir> slashPorts(Grid grid, int row, int col) {
        boolean left = neighborSupports(grid, row, col, Dir.LEFT);
        boolean right = neighborSupports(grid, row, col, Dir.RIGHT);
        boolean up = neighborSupports(grid, row, col, Dir.UP);
        boolean down = neighborSupports(grid, row, col, Dir.DOWN);
        EnumSet<Dir> ports = EnumSet.noneOf(Dir.class);
        if (right && down && !left && !up) {
            ports.add(Dir.RIGHT);
            ports.add(Dir.DOWN);
        } else if (left && up && !right && !down) {
            ports.add(Dir.LEFT);
            ports.add(Dir.UP);
        } else if (left && down && !right && !up) {
            ports.add(Dir.LEFT);
            ports.add(Dir.DOWN);
        } else if (right && up && !left && !down) {
            ports.add(Dir.RIGHT);
            ports.add(Dir.UP);
        }
        return ports;
    }

    private static EnumSet<Dir> backslashPorts(Grid grid, int row, int col) {
        boolean left = neighborSupports(grid, row, col, Dir.LEFT);
        boolean right = neighborSupports(grid, row, col, Dir.RIGHT);
        boolean up = neighborSupports(grid, row, col, Dir.UP);
        boolean down = neighborSupports(grid, row, col, Dir.DOWN);
        EnumSet<Dir> ports = EnumSet.noneOf(Dir.class);
        if (left && down && !right && !up) {
            ports.add(Dir.LEFT);
            ports.add(Dir.DOWN);
        } else if (right && up && !left && !down) {
            ports.add(Dir.RIGHT);
            ports.add(Dir.UP);
        } else if (right && down && !left && !up) {
            ports.add(Dir.RIGHT);
            ports.add(Dir.DOWN);
        } else if (left && up && !right && !down) {
            ports.add(Dir.LEFT);
            ports.add(Dir.UP);
        }
        return ports;
    }

    private static boolean neighborSupports(Grid grid, int row, int col, Dir dir) {
        int nr = row + dir.dy;
        int nc = col + dir.dx;
        char ch = grid.charAt(nr, nc);
        return rawSupports(ch, dir.opposite());
    }

    private static boolean rawSupports(char ch, Dir dir) {
        switch (dir) {
            case LEFT:
                return ch == '-' || ch == '=' || ch == '+' || ch == '*' || ch == '>';
            case RIGHT:
                return ch == '-' || ch == '=' || ch == '+' || ch == '*' || ch == '<';
            case UP:
                return ch == '|' || ch == ':' || ch == '+' || ch == '*' || ch == 'v' || ch == 'V';
            case DOWN:
                return ch == '|' || ch == ':' || ch == '+' || ch == '*' || ch == '^';
            default:
                return false;
        }
    }

    private static List<Node> simplifyPolygon(List<Node> polygon) {
        List<Node> simple = new ArrayList<>();
        for (Node node : polygon) {
            if (simple.isEmpty()) {
                simple.add(node);
                continue;
            }
            Node prev = simple.get(simple.size() - 1);
            if (prev.row == node.row && prev.col == node.col) {
                continue;
            }
            simple.add(node);
        }
        boolean changed = true;
        while (changed && simple.size() >= 3) {
            changed = false;
            for (int i = 0; i < simple.size(); i++) {
                Node a = simple.get((i - 1 + simple.size()) % simple.size());
                Node b = simple.get(i);
                Node c = simple.get((i + 1) % simple.size());
                if ((a.col == b.col && b.col == c.col) || (a.row == b.row && b.row == c.row)) {
                    simple.remove(i);
                    changed = true;
                    break;
                }
            }
        }
        return simple;
    }

    private static double polygonArea(List<Node> polygon) {
        double area = 0.0;
        for (int i = 0; i < polygon.size(); i++) {
            Node a = polygon.get(i);
            Node b = polygon.get((i + 1) % polygon.size());
            area += (a.col * b.row) - (b.col * a.row);
        }
        return area / 2.0;
    }

    private static boolean contains(List<Node> polygon, int col, int row) {
        if (pointOnPolygon(polygon, col, row)) {
            return false;
        }
        boolean inside = false;
        for (int i = 0, j = polygon.size() - 1; i < polygon.size(); j = i++) {
            double xi = polygon.get(i).col;
            double yi = polygon.get(i).row;
            double xj = polygon.get(j).col;
            double yj = polygon.get(j).row;
            boolean intersect = ((yi > row) != (yj > row))
                && (col < (xj - xi) * (row - yi) / ((yj - yi) == 0 ? 1e-9 : (yj - yi)) + xi);
            if (intersect) {
                inside = !inside;
            }
        }
        return inside;
    }

    private static boolean pointOnPolygon(List<Node> polygon, int col, int row) {
        for (int i = 0; i < polygon.size(); i++) {
            Node a = polygon.get(i);
            Node b = polygon.get((i + 1) % polygon.size());
            if (a.col == b.col && col == a.col && between(row, a.row, b.row)) {
                return true;
            }
            if (a.row == b.row && row == a.row && between(col, a.col, b.col)) {
                return true;
            }
        }
        return false;
    }

    private static boolean between(int value, int a, int b) {
        return value >= Math.min(a, b) && value <= Math.max(a, b);
    }

    private static int minCol(Face face) {
        int value = Integer.MAX_VALUE;
        for (Node node : face.polygon) {
            value = Math.min(value, node.col);
        }
        return value;
    }

    private static int maxCol(Face face) {
        int value = Integer.MIN_VALUE;
        for (Node node : face.polygon) {
            value = Math.max(value, node.col);
        }
        return value;
    }

    private static int minRow(Face face) {
        int value = Integer.MAX_VALUE;
        for (Node node : face.polygon) {
            value = Math.min(value, node.row);
        }
        return value;
    }

    private static int maxRow(Face face) {
        int value = Integer.MIN_VALUE;
        for (Node node : face.polygon) {
            value = Math.max(value, node.row);
        }
        return value;
    }

    private static RowText parseRowText(String raw, int startCol, int row) {
        Matcher tagMatcher = TAG_PATTERN.matcher(raw);
        String tag = null;
        if (tagMatcher.find()) {
            tag = tagMatcher.group(1);
            raw = tagMatcher.replaceAll("");
        }
        Matcher colorMatcher = COLOR_PATTERN.matcher(raw);
        Color fill = null;
        if (colorMatcher.find()) {
            fill = NAMED_COLORS.get(colorMatcher.group(1));
            raw = colorMatcher.replaceAll("");
        }
        int bullet = raw.indexOf(" o ");
        if (bullet >= 0) {
            raw = raw.substring(0, bullet) + " •" + raw.substring(bullet + 3);
        }
        int left = 0;
        int right = raw.length() - 1;
        while (left < raw.length() && raw.charAt(left) == ' ') {
            left++;
        }
        while (right >= left && raw.charAt(right) == ' ') {
            right--;
        }
        TextItem text = null;
        if (left <= right) {
            text = new TextItem(raw.substring(left, right + 1), startCol + left, row, null, true);
        }
        return new RowText(tag, fill, text);
    }

    private static boolean isRectangle(List<Node> polygon) {
        if (polygon.size() != 4) {
            return false;
        }
        for (int i = 0; i < 4; i++) {
            Node a = polygon.get(i);
            Node b = polygon.get((i + 1) % 4);
            if (a.col != b.col && a.row != b.row) {
                return false;
            }
        }
        return true;
    }

    private static boolean hasRoundedCorners(List<Node> polygon, Grid grid) {
        for (Node node : polygon) {
            char ch = grid.charAt(node.row, node.col);
            if (ch == '/' || ch == '\\') {
                return true;
            }
        }
        return false;
    }

    private static Color chooseTextColor(Color fill) {
        double luminance = (0.299 * fill.getRed() + 0.587 * fill.getGreen() + 0.114 * fill.getBlue()) / 255.0;
        return luminance < 0.45 ? Color.WHITE : Color.BLACK;
    }

    private static int fitFontSize(String text, int col, int row, ShapeRegion shape, double scale) {
        int base = scaledValue(15, scale);
        int available = Math.max(10, (shape.maxCol - col + 1) * scaledValue(CELL_W, scale));
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        int size = base;
        while (size > Math.max(7, scaledValue(7, scale))) {
            graphics.setFont(new Font("Courier", Font.BOLD, size));
            FontMetrics metrics = graphics.getFontMetrics();
            if (metrics.stringWidth(text) <= available) {
                break;
            }
            size--;
        }
        graphics.dispose();
        return size;
    }

    private static int textStartX(int col, double scale) {
        return scaledValue((int) Math.round((col + 0.5) * CELL_W), scale) - scaledValue(3, scale);
    }

    private static int textBaselineY(int row, double scale) {
        return scaledValue((int) Math.round((row + 0.5) * CELL_H), scale) + scaledValue(5, scale);
    }

    private static int scaledValue(int base, double scale) {
        return (int) Math.floor(base * scale + 1e-9);
    }

    private static double coordX(int col, double scale) {
        return Math.floor((col + 0.5) * CELL_W * scale + 1e-9);
    }

    private static double coordY(int row, double scale) {
        return Math.floor((row + 0.5) * CELL_H * scale + 1e-9);
    }

    private static String colorToSvg(Color color, boolean keepAlpha) {
        String rgb = String.format(Locale.ROOT, "#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
        if (!keepAlpha) {
            return rgb;
        }
        return rgb;
    }

    private static String escapeXml(String value) {
        return value.replace("&", "&amp;").replace("<", "&lt;").replace("'", "&apos;");
    }

    private static String escapeCdata(String value) {
        return value.replace("]]>", "]]]]><![CDATA[>");
    }

    private static String oneDecimal(double value) {
        return String.format(Locale.ROOT, "%.1f", value);
    }

    private static String circlePath(double cx, double cy, double r) {
        return "M" + oneDecimal(cx + r) + " " + oneDecimal(cy) +
            " C" + oneDecimal(cx + r) + " " + oneDecimal(cy + r * 0.5522847498) +
            " " + oneDecimal(cx + r * 0.5522847498) + " " + oneDecimal(cy + r) +
            " " + oneDecimal(cx) + " " + oneDecimal(cy + r) +
            " C" + oneDecimal(cx - r * 0.5522847498) + " " + oneDecimal(cy + r) +
            " " + oneDecimal(cx - r) + " " + oneDecimal(cy + r * 0.5522847498) +
            " " + oneDecimal(cx - r) + " " + oneDecimal(cy) +
            " C" + oneDecimal(cx - r) + " " + oneDecimal(cy - r * 0.5522847498) +
            " " + oneDecimal(cx - r * 0.5522847498) + " " + oneDecimal(cy - r) +
            " " + oneDecimal(cx) + " " + oneDecimal(cy - r) +
            " C" + oneDecimal(cx + r * 0.5522847498) + " " + oneDecimal(cy - r) +
            " " + oneDecimal(cx + r) + " " + oneDecimal(cy - r * 0.5522847498) +
            " " + oneDecimal(cx + r) + " " + oneDecimal(cy) + " z";
    }

    private static Path2D arrowPath(char ch, double cx, double cy, double scale) {
        double dx = 5.0 * scale;
        double dy = 7.0 * scale;
        Path2D path = new Path2D.Double();
        switch (ch) {
            case '>':
                path.moveTo(cx - dx, cy - dy);
                path.lineTo(cx + dx, cy);
                path.lineTo(cx - dx, cy + dy);
                break;
            case '<':
                path.moveTo(cx + dx, cy - dy);
                path.lineTo(cx - dx, cy);
                path.lineTo(cx + dx, cy + dy);
                break;
            case '^':
                path.moveTo(cx - dx, cy + dy);
                path.lineTo(cx, cy - dy);
                path.lineTo(cx + dx, cy + dy);
                break;
            default:
                path.moveTo(cx - dx, cy - dy);
                path.lineTo(cx, cy + dy);
                path.lineTo(cx + dx, cy - dy);
                break;
        }
        path.closePath();
        return path;
    }

    private static String pathToSvg(Path2D path) {
        StringBuilder out = new StringBuilder();
        double[] coords = new double[6];
        for (java.awt.geom.PathIterator it = path.getPathIterator(null); !it.isDone(); it.next()) {
            int type = it.currentSegment(coords);
            switch (type) {
                case java.awt.geom.PathIterator.SEG_MOVETO:
                    appendSvg(out, "M", coords[0], coords[1]);
                    break;
                case java.awt.geom.PathIterator.SEG_LINETO:
                    appendSvg(out, "L", coords[0], coords[1]);
                    break;
                case java.awt.geom.PathIterator.SEG_QUADTO:
                    appendSvg(out, "Q", coords[0], coords[1], coords[2], coords[3]);
                    break;
                case java.awt.geom.PathIterator.SEG_CUBICTO:
                    appendSvg(out, "C", coords[0], coords[1], coords[2], coords[3], coords[4], coords[5]);
                    break;
                case java.awt.geom.PathIterator.SEG_CLOSE:
                    out.append(" z");
                    break;
                default:
                    break;
            }
        }
        return out.toString().trim();
    }

    private static void appendSvg(StringBuilder out, String op, double... values) {
        if (out.length() > 0) {
            out.append(' ');
        }
        out.append(op);
        for (int i = 0; i < values.length; i += 2) {
            out.append(oneDecimal(values[i])).append(' ').append(oneDecimal(values[i + 1]));
            if (i + 2 < values.length) {
                out.append(' ');
            }
        }
    }

    private static BufferedImage blur(BufferedImage source, int radius) {
        int size = Math.max(3, radius * 2 + 1);
        float[] data = gaussianKernel(size, Math.max(0.8f, radius / 2.0f));
        Kernel kernel = new Kernel(size, 1, data);
        ConvolveOp horizontal = new ConvolveOp(kernel, ConvolveOp.EDGE_NO_OP, null);
        BufferedImage temp = horizontal.filter(source, null);
        Kernel verticalKernel = new Kernel(1, size, data);
        ConvolveOp vertical = new ConvolveOp(verticalKernel, ConvolveOp.EDGE_NO_OP, null);
        return vertical.filter(temp, null);
    }

    private static float[] gaussianKernel(int size, float sigma) {
        float[] data = new float[size];
        int half = size / 2;
        float sum = 0f;
        for (int i = 0; i < size; i++) {
            int x = i - half;
            float value = (float) Math.exp(-(x * x) / (2f * sigma * sigma));
            data[i] = value;
            sum += value;
        }
        for (int i = 0; i < size; i++) {
            data[i] /= sum;
        }
        return data;
    }

    private static Rect boundingRect(List<Node> polygon, double scale) {
        double left = Double.POSITIVE_INFINITY;
        double right = Double.NEGATIVE_INFINITY;
        double top = Double.POSITIVE_INFINITY;
        double bottom = Double.NEGATIVE_INFINITY;
        for (Node node : polygon) {
            left = Math.min(left, coordX(node.col, scale));
            right = Math.max(right, coordX(node.col, scale));
            top = Math.min(top, coordY(node.row, scale));
            bottom = Math.max(bottom, coordY(node.row, scale));
        }
        return new Rect(left, top, right, bottom);
    }

    private static final class Rect {
        final double left;
        final double top;
        final double right;
        final double bottom;

        Rect(double left, double top, double right, double bottom) {
            this.left = left;
            this.top = top;
            this.right = right;
            this.bottom = bottom;
        }

        double width() {
            return right - left;
        }

        double height() {
            return bottom - top;
        }

        double centerX() {
            return (left + right) / 2.0;
        }

        double centerY() {
            return (top + bottom) / 2.0;
        }
    }
}

